  foreach(var id in new[]{"event","other"}){var e=new SessionEvent{Id=id,Title=id,ScheduledDate="2099-01-01T00:00:00.000Z",CreatedAt="2026-10-01T00:00:00.000Z",ManualPhaseOverride=true};e.Phases.Add(new(){EventId=id,Kind="Hidden",Name="Hidden",IsActive=true});e.Phases.Add(new(){EventId=id,Kind="View",Name="View"});e.Phases.Add(new(){Id=id+"-custom",EventId=id,Kind="Custom",Name="Signup",MaxPicks=-1});if(id=="event")e.Admins.Add(new(){EventId=id,UserId="manager",GrantedAt=e.CreatedAt});db.SessionEvents.Add(e);}
  db.UserProfiles.Add(new(){UserId="performer",Reading="ねいてぃぶ",CallName="ねい",SocialJson="[{\"Service\":\"PRIVATE SOCIAL\",\"Url\":\"https://private.invalid/\"}]"});
  db.EventPartDefinitions.AddRange(new EventPartDefinition{Id="vo",EventId="event",Name="Voice",NormalizedName="VOICE",Category="Sing"},new EventPartDefinition{Id="gt",EventId="event",Name="Guitar",NormalizedName="GUITAR",Category="Play"});db.Songs.Add(new(){Id="song",EventId="event",Title="Current song",PerformanceSeconds=60});db.SongParts.AddRange(new SongPart{Id="voice",EventId="event",SongId="song",PartDefinitionId="vo",AssignedUserId="performer",PhaseId="event-custom"},new SongPart{Id="guitar",EventId="event",SongId="song",PartDefinitionId="gt",AssignedUserId="performer",PhaseId="event-custom"});db.EventSpectators.Add(new(){EventId="event",UserId="spectator",RegisteredAt="2026-10-01T00:00:00.000Z",RegisteredBy="admin"});db.EventQuestions.Add(new(){Id="private",EventId="event",Text="PRIVATE QUESTION",Type="Text"});db.EventQuestionAnswers.Add(new(){QuestionId="private",UserId="viewer",Value="PRIVATE ANSWER",UpdatedAt="2026-10-01T00:00:00.000Z"});await db.SaveChangesAsync();
 }
 await Deny<UnauthorizedAccessException>(()=>core.ReadReceptionRosterAsync(new ClaimsPrincipal(),"event"),"Anonymous cannot read receptionist roster");await Deny<UnauthorizedAccessException>(()=>core.ReadReceptionRosterAsync(viewer,"event"),"Forged Admin role claim does not grant event management");await Deny<UnauthorizedAccessException>(()=>core.ReadReceptionRosterAsync(manager,"other"),"Assigned manager cannot inspect another event");await Deny<UnauthorizedAccessException>(()=>core.ReadReceptionRosterAsync(admin,"missing"),"Unknown event denied");
 await Deny<UnauthorizedAccessException>(()=>core.ReadParticipantRosterAsync(new ClaimsPrincipal(),"event"),"Anonymous cannot read public participant roster");
 await Deny<UnauthorizedAccessException>(()=>core.ReadParticipantRosterAsync(viewer,"event"),"Hidden participant roster remains hidden from unassigned viewer");
 var publicRoster=await core.ReadParticipantRosterAsync(manager,"event");
 Check(publicRoster.ParticipantCount==2&&publicRoster.People.Length==2,"Participant roster groups current performers and spectators into one row per user");
 var publicPerformer=publicRoster.People.Single(x=>x.UserId=="performer");
 Check(publicPerformer.Parts.Length==2&&publicPerformer.Parts.All(x=>x.SongTitle=="Current song")&&publicPerformer.Parts.Select(x=>x.PartName).Order().SequenceEqual(new[]{"Guitar","Voice"}),"Roster preserves both same-song part assignments rather than collapsing roles");
 Check(publicRoster.People.Single(x=>x.UserId=="spectator").Spectator&&publicRoster.People.Single(x=>x.UserId=="spectator").Parts.Length==0,"Public spectator row does not invent musical roles");
 var publicJson=JsonSerializer.Serialize(publicRoster);
 Check(!publicJson.Contains("PRIVATE")&&!publicJson.Contains("\"Reading\":")&&!publicJson.Contains("\"Current\":")&&!publicJson.Contains("\"Token\":"),"Public roster excludes emails answers readings receipt status notes and codes");
 await using(var db=await factory.CreateDbContextAsync()){var phases=await db.Set<EventPhase>().Where(x=>x.EventId=="event").ToArrayAsync();phases.Single(x=>x.IsActive).IsActive=false;await db.SaveChangesAsync();phases.Single(x=>x.Kind=="View").IsActive=true;await db.SaveChangesAsync();}
 Check((await core.ReadParticipantRosterAsync(viewer,"event")).People.Length==2,"Visible event roster is readable by ordinary event viewers without receptionist privilege");
 await using(var db=await factory.CreateDbContextAsync()){var phases=await db.Set<EventPhase>().Where(x=>x.EventId=="event").ToArrayAsync();phases.Single(x=>x.IsActive).IsActive=false;await db.SaveChangesAsync();phases.Single(x=>x.Kind=="Hidden").IsActive=true;await db.SaveChangesAsync();}
