 var initial=await core.ReadReceptionRosterAsync(manager,"event");Check(initial.CompletedCount==0&&initial.UnreceivedCount==2&&initial.People.All(x=>x.Current is null),"No receipt starts as exact current unreceived population");
 var rt=await core.ReadReceptionTargetAsync(admin,"event","performer");await core.CompleteManualReceptionAsync(admin,"event",new(Guid.NewGuid().ToString(),"performer",rt.EventVersion,rt.ParticipantVersion,rt.ReceptionVersion,true,"PRIVATE RECEIPT NOTE"));
 var status=await core.ReadReceptionRosterAsync(manager,"event");Check(status.CompletedCount==1&&status.UnreceivedCount==1&&status.People.Single(x=>x.UserId=="performer").Current!.Method=="Manual","Active receipt updates unique current participant status without counting same-song parts twice");
 Check(!JsonSerializer.Serialize(status).Contains("PRIVATE RECEIPT NOTE")&&!JsonSerializer.Serialize(status).Contains("PRIVATE.invalid"),"Roster status excludes receipt notes and email");
 status=await core.ReadReceptionRosterAsync(manager,"event","missing");Check(status.MatchCount==0&&status.CompletedCount==1&&status.UnreceivedCount==1,"Search matches never change full current receipt denominator");
 rt=await core.ReadReceptionTargetAsync(admin,"event","performer");await core.CancelReceptionAsync(admin,"event",new(Guid.NewGuid().ToString(),"performer",rt.Current!.Id,rt.ReceptionVersion,true));status=await core.ReadReceptionRosterAsync(manager,"event");Check(status.CompletedCount==0&&status.UnreceivedCount==2&&status.People.All(x=>x.Current is null),"Cancellation returns current roster status to unreceived while preserving history");
 rt=await core.ReadReceptionTargetAsync(admin,"event","spectator");await core.CompleteManualReceptionAsync(admin,"event",new(Guid.NewGuid().ToString(),"spectator",rt.EventVersion,rt.ParticipantVersion,rt.ReceptionVersion,true,""));
 var p=await core.ReadReceptionRosterAsync(manager,"event");Check(p.ParticipantCount==2&&p.MatchCount==2&&p.People.Length==2,"Hidden manager roster is current unique performer plus spectator population");Check(p.People.All(x=>x.UserId!="viewer"),"Historical question answer does not count as current registration");var performer=p.People.Single(x=>x.UserId=="performer");Check(!performer.Spectator&&performer.Songs.SequenceEqual(new[]{"Current song"}),"Two same-song parts yield one song and one participant");Check(p.People.Single(x=>x.UserId=="spectator").Spectator&&p.People.Single(x=>x.UserId=="spectator").Songs.Length==0,"Spectator is distinguished without invented performance");var json=JsonSerializer.Serialize(p);Check(!json.Contains("PRIVATE.invalid")&&!json.Contains("PRIVATE ANSWER")&&!json.Contains("PRIVATE QUESTION")&&!json.Contains("PRIVATE SOCIAL"),"Projection excludes email private answers questionnaire and social details");
 Check((await core.ReadReceptionRosterAsync(manager,"event","abc")).People.Single().UserId=="performer","Latin case and full-width display name normalized");Check((await core.ReadReceptionRosterAsync(manager,"event","ａ ｂ ｃ")).MatchCount==1,"Width and whitespace normalized in search query");Check((await core.ReadReceptionRosterAsync(manager,"event","ネイティブ")).MatchCount==1,"Katakana query matches hiragana reading");Check((await core.ReadReceptionRosterAsync(manager,"event","ﾈｲﾃｨﾌﾞ")).MatchCount==1,"Half-width Katakana search matches current participant");Check((await core.ReadReceptionRosterAsync(manager,"event","missing")).MatchCount==0,"No match is empty without changing participant denominator");await Deny<ValidationException>(()=>core.ReadReceptionRosterAsync(manager,"event",new string('a',201)),"Search input transport bound enforced");
 await using(var db=await factory.CreateDbContextAsync()){db.EventSpectators.Remove(await db.EventSpectators.SingleAsync());await db.SaveChangesAsync();}Check((await core.ReadReceptionRosterAsync(manager,"event")).ParticipantCount==1,"Removed spectator disappears on next read");status=await core.ReadReceptionRosterAsync(manager,"event");Check(status.CompletedCount==0&&status.UnreceivedCount==1,"Retained receipt for withdrawn spectator never inflates current received count");await using(var db=await factory.CreateDbContextAsync()){foreach(var part in await db.SongParts.ToArrayAsync()){part.AssignedUserId=null;part.PhaseId=null;}await db.SaveChangesAsync();}Check((await core.ReadReceptionRosterAsync(manager,"event")).ParticipantCount==0,"Removed final assignments disappear without historical-answer resurrection");
 await using(var db=await factory.CreateDbContextAsync()){for(var i=0;i<105;i++){var id="bounded"+i;db.Users.Add(new(){Id=id,DisplayName=id,EmailConfirmed=true,Enabled=true});db.EventSpectators.Add(new(){EventId="event",UserId=id,RegisteredAt="2026-10-01T00:00:00.000Z",RegisteredBy="admin"});}await db.SaveChangesAsync();}p=await core.ReadReceptionRosterAsync(admin,"event");Check(p.ParticipantCount==105&&p.MatchCount==105&&p.People.Length==100&&p.MoreMatches,"Bounded roster reports exact denominator and more matches instead of pretending completeness");Check((await core.ReadReceptionRosterAsync(admin,"event","bounded104")).People.Single().UserId=="bounded104","Search can retrieve a target beyond first 100 default rows");
 rt=await core.ReadReceptionTargetAsync(admin,"event","bounded99");await core.CompleteManualReceptionAsync(admin,"event",new(Guid.NewGuid().ToString(),"bounded99",rt.EventVersion,rt.ParticipantVersion,rt.ReceptionVersion,true,""));status=await core.ReadReceptionRosterAsync(admin,"event");Check(status.CompletedCount==1&&status.UnreceivedCount==104&&status.People.All(x=>x.Current is null),"Full count includes received participant beyond bounded display without pretending first page is complete");status=await core.ReadReceptionRosterAsync(admin,"event","bounded99");Check(status.People.Single().Current is not null&&status.CompletedCount==1&&status.UnreceivedCount==104,"Search exposes bounded-away current receipt without changing global totals");

 var firstPage=await core.ReadParticipantRosterAsync(admin,"event");var secondPage=await core.ReadParticipantRosterAsync(admin,"event",firstPage.NextUserId);
